import 'package:aivexus_interval_union/interval_union.dart';
void main() {
  final input = <(int,int)>[(5, 9), (1, 3), (3, 6), (15, 16)];
  final original = List<(int,int)>.from(input);
  final out = normalizeIntervals(input);
  if (out.length != 2 || out[0] != (1, 9) || out[1] != (15, 16)) throw StateError('merge overlap/touch failed: $out');
  if (input.toString() != original.toString()) throw StateError('input was mutated');
  if (normalizeIntervals(<(int,int)>[]).isNotEmpty) throw StateError('empty input failed');
  var rejected = false;
  try { normalizeIntervals(<(int,int)>[(4, 4)]); } on ArgumentError { rejected = true; }
  if (!rejected) throw StateError('invalid half-open range accepted');
  print('PASS: independently consumed LLM-generated interval module');
}

import 'package:aivexus_delta_codec/delta_codec.dart';
void main() {
  final samples = <int>[12, -4, -4, 9, 0];
  final original = List<int>.from(samples);
  final encoded = encodeDeltas(samples);
  if (encoded.toString() != '[12, -16, 0, 13, -9]') throw StateError('encoding failed: $encoded');
  if (decodeDeltas(encoded).toString() != samples.toString()) throw StateError('decoding failed');
  if (samples.toString() != original.toString()) throw StateError('input mutated');
  if (encodeDeltas(<int>[]).isNotEmpty || decodeDeltas(<int>[]).isNotEmpty) throw StateError('empty input failed');
  print('PASS: independently consumed LLM-generated delta module');
}
